需要登录后才能搜索下载，每日下载有次数限制。同站：256中文https://www.256zw.cc/
*/
		var sz = source.getVariable();
		if(result.match(/没有权限使用搜索/)){
			if(sz == 1){
		var login = source.loginUrl;
  java.startBrowserAwait(login,"登陆");
  java.toast("已登陆，重新搜索即可获取");
		}else{
			java.toast("未登陆，登陆后才能搜索");
			result = "";
			}
	}else{
		result = result;
		}

